#!/usr/bin/env bash
set -euo pipefail

# Format codebase
if [ -f "tools/google-java-format.jar" ]; then
  # The parser sources are generated by ANTLR; format only handwritten Java.
  find src -name '*.java' ! -path 'src/com/comcast/oscar/parser/tlv*.java' -print0 \
    | xargs -0 java -jar tools/google-java-format.jar --replace

else
  echo "Missing tools/google-java-format.jar; run tools/setup-formatter.sh" >&2
  exit 1
fi

# Test quality/release helpers without changing Git refs.
python3 -m unittest discover -s tools/quality -p 'test_*.py'
python3 -m unittest discover -s tools/release -p 'test_*.py'

# Hygiene and compile
tools/code-hygene-checker.sh

# Tests
./scripts/verify.sh
